mapper.select:
SELECT p.*, CASE WHEN p.code = 'default' THEN ( SELECT COUNT(*) FROM sys_permission perm WHERE perm.is_deleted = 0 AND perm.type IN ('menu', 'button') ) ELSE ( SELECT COUNT(*) FROM sys_tenant_package_permission tpp INNER JOIN sys_permission perm ON perm.id = tpp.permission_id AND perm.is_deleted = 0 WHERE tpp.package_id = p.id AND tpp.is_deleted = 0 AND perm.type IN ('menu', 'button') ) END AS permission_count FROM sys_tenant_package p WHERE p.is_deleted = 0
AND (p.name LIKE CONCAT('%', #{req.keyword}, '%') OR p.code LIKE CONCAT('%', #{req.keyword}, '%'))
AND p.status = #{req.status}
ORDER BY permission_count ${req.safeOrderDirection()}
ORDER BY p.${req.safeOrderBy()} ${req.safeOrderDirection()}
ORDER BY p.sort ASC
